(function(E){ const x = E["exam-03"] = E["exam-03"] || {units:{}}; (x.units = x.units || {})["x03-l2"] = {"id":"x03-l2","patterns":["L2-work"],"title":{"en":"Listening Part 2: a business talk","tr":"Listening Part 2: bir işletme konuşması","fa":"Listening Part 2: صحبتی درباره‌ی کسب‌وکار"},"objective":{"en":"In this lesson you will learn to follow one speaker talking about her small business: choose TWO answers from five, answer two multiple-choice questions, and match pieces of advice to topics when two options are traps.","tr":"Bu derste küçük işletmesini anlatan tek bir konuşmacıyı takip etmeyi öğreneceksin: beş seçenekten İKİ cevap seçecek, iki çoktan seçmeli soruyu cevaplayacak ve iki seçeneğin tuzak olduğu bir durumda tavsiyeleri konularla eşleştireceksin.","fa":"در این درس یاد می‌گیری صحبت یک نفر درباره‌ی کسب‌وکار کوچکش را دنبال کنی: از پنج گزینه دو جواب انتخاب کنی، به دو سؤال چندگزینه‌ای جواب بدهی و توصیه‌ها را به موضوع‌ها وصل کنی، وقتی دو گزینه دام‌اند."},"sessions":[["explain"],["drill"],["exit"]],"explain":{"title":{"en":"Listening Part 2: a business talk","tr":"Listening Part 2: bir işletme konuşması","fa":"Listening Part 2: صحبتی درباره‌ی کسب‌وکار"},"objective":{"en":"In this lesson you will learn to follow one speaker talking about her small business: choose TWO answers from five, answer two multiple-choice questions, and match pieces of advice to topics when two options are traps.","tr":"Bu derste küçük işletmesini anlatan tek bir konuşmacıyı takip etmeyi öğreneceksin: beş seçenekten İKİ cevap seçecek, iki çoktan seçmeli soruyu cevaplayacak ve iki seçeneğin tuzak olduğu bir durumda tavsiyeleri konularla eşleştireceksin.","fa":"در این درس یاد می‌گیری صحبت یک نفر درباره‌ی کسب‌وکار کوچکش را دنبال کنی: از پنج گزینه دو جواب انتخاب کنی، به دو سؤال چندگزینه‌ای جواب بدهی و توصیه‌ها را به موضوع‌ها وصل کنی، وقتی دو گزینه دام‌اند."},"stats":[{"label":{"en":"Questions","tr":"Soru","fa":"سؤال"},"value":"10"},{"label":{"en":"Speakers","tr":"Konuşan","fa":"گوینده"},"value":"1"},{"label":{"en":"Box","tr":"Kutu","fa":"کادر"},"value":"A-F"}],"context":{"eyebrow":{"en":"1 The context","tr":"1 Bağlam","fa":"۱ بافت"},"head":{"en":"This exam: a market coffee stall","tr":"Bu sınav: pazarda bir kahve tezgâhı","fa":"این آزمون: یک غرفه‌ی قهوه در بازار"},"intro":{"en":"Part 2 is one speaker giving information to a group. Talks about work (starting a job, training, running a business) are one of the most frequent situations. The speaker often reports common beliefs and then corrects them.","tr":"Part 2, bir gruba bilgi veren tek bir konuşmacıdır. İşle ilgili konuşmalar (işe başlamak, eğitim, bir işletme yürütmek) en sık durumlardan biridir. Konuşan çoğu zaman yaygın inanışları aktarır, sonra onları düzeltir.","fa":"Part 2 یک گوینده است که به یک گروه اطلاعات می‌دهد. صحبت‌هایی درباره‌ی کار (شروع یک شغل، آموزش، گرداندن کسب‌وکار) یکی از پرتکرارترین موقعیت‌هاست. گوینده اغلب باورهای رایج را نقل و بعد اصلاحشان می‌کند."},"technique":{"en":"2 The technique","tr":"2 Teknik","fa":"۲ تکنیک"},"labels":{"asks":{"en":"What this part is about","tr":"Bu kısım ne hakkında","fa":"این بخش درباره‌ی چیست"},"fields":{"en":"Headings you will see","tr":"Göreceğin başlıklar","fa":"عنوان‌هایی که می‌بینی"},"words":{"en":"Words that carry the answers","tr":"Cevabı taşıyan kelimeler","fa":"کلمه‌هایی که جواب را می‌آورند"},"a":{"en":"On the paper","tr":"Kâğıtta","fa":"روی برگه"},"b":{"en":"What you hear or read","tr":"Duyduğun ya da okuduğun","fa":"چیزی که می‌شنوی یا می‌خوانی"},"traps":{"en":"Traps","tr":"Tuzaklar","fa":"دام‌ها"},"example":{"en":"Example","tr":"Örnek","fa":"نمونه"},"ideas":{"en":"Ideas","tr":"Fikirler","fa":"ایده‌ها"}},"cards":[{"id":"x03-l2-ctx","exam":true,"patterns":["L2-work"],"often":{"pattern":"L2-work","n":9,"of":40,"label":{"en":"Comes up often in the real exam: 9 of the last 40 tests","tr":"Gerçek sınavda sık çıkar: son 40 sınavın 9’unda","fa":"در آزمون واقعی زیاد می‌آید: در ۹ آزمون از ۴۰ آزمونِ اخیر"}},"title":{"en":"A talk by a small-business owner","tr":"Küçük bir işletme sahibinin konuşması","fa":"صحبت صاحب یک کسب‌وکار کوچک"},"asks":{"en":"The owner of a market stall tells a class how she started: what she did first, the problems of the first year, why she chose a market, and short advice on several practical areas.","tr":"Bir pazar tezgâhının sahibi bir sınıfa nasıl başladığını anlatıyor: önce ne yaptığını, ilk yılın sorunlarını, neden pazarı seçtiğini ve birkaç pratik konuda kısa tavsiyeler.","fa":"صاحب یک غرفه‌ی بازار برای یک کلاس تعریف می‌کند چطور شروع کرد: اول چه کرد، مشکل‌های سال اول، چرا بازار را انتخاب کرد و توصیه‌های کوتاه درباره‌ی چند موضوع عملی."},"fields":["Before opening","Money","First-year problems","Why a market","The licence","Advice: prices, social media, suppliers, menu"],"words":[{"a":"run a stall","b":"own and work at a stall","tr":"tezgâh işletmek","fa":"غرفه گرداندن"},{"a":"savings","b":"money I had put aside","tr":"birikim","fa":"پس‌انداز"},{"a":"lend","b":"give money that must be paid back","tr":"borç vermek","fa":"قرض دادن"},{"a":"takings","b":"the money a shop or stall makes in a day","tr":"hasılat","fa":"دخل، فروش روزانه"},{"a":"break down","b":"stop working","tr":"bozulmak","fa":"خراب شدن"},{"a":"complain about","b":"say you are unhappy with","tr":"... hakkında şikâyet etmek","fa":"از ... شکایت کردن"},{"a":"the real advantage","b":"the main reason it is better","tr":"asıl avantaj","fa":"مزیت اصلی"},{"a":"licence","b":"official permission","tr":"ruhsat","fa":"مجوز"},{"a":"apply early","b":"ask for it in good time","tr":"erken başvurmak","fa":"زود درخواست دادن"},{"a":"supplier","b":"the company that sells you goods","tr":"tedarikçi","fa":"تأمین‌کننده"},{"a":"free samples","b":"small amounts given away to try","tr":"ücretsiz numune","fa":"نمونه‌ی رایگان"},{"a":"a short menu","b":"only a few choices","tr":"kısa bir menü","fa":"منوی کوتاه"}],"traps":[{"en":"\"Everyone assumes it’s because...\" introduces what other people think. The speaker’s reason comes after \"but that wasn’t really the reason\".","tr":"\"Herkes bunun nedeninin ... olduğunu sanıyor\" başkalarının düşündüğünü getirir. Konuşanın nedeni \"ama asıl neden bu değildi\"den sonra gelir.","fa":"«همه فکر می‌کنند دلیلش ... است» فکرِ دیگران را می‌آورد. دلیل خودِ گوینده بعد از «اما دلیل اصلی این نبود» می‌آید."},{"en":"In the matching task two options in the box are mentioned and rejected (\"I tried it and it didn’t work\"). Mentioned is not the same as advised.","tr":"Eşleştirmede kutudaki iki seçenekten söz edilir ve reddedilir (\"Denedim, işe yaramadı\"). Söz edilmek, tavsiye edilmekle aynı şey değildir.","fa":"در تمرین جورکردن از دو گزینه‌ی کادر اسم برده و رد می‌شوند («امتحانش کردم و جواب نداد»). اسم بردن با توصیه کردن یکی نیست."}],"example":{"lines":[["Speaker","Some people say you should open every day. I tried that, and I was exhausted. Four days a week is plenty."]],"item":"What does the speaker advise about opening days? A open every day  B open four days a week  C open at weekends only","answer":"B","why":{"en":"Opening every day is what \"some people say\", and she rejects it. \"Four days a week is plenty.\"","tr":"Her gün açmak \"bazı insanların söylediği\" şey ve o bunu reddediyor. \"Haftada dört gün yeter.\"","fa":"هر روز باز کردن چیزی است که «بعضی‌ها می‌گویند» و او ردش می‌کند. «هفته‌ای چهار روز کافی است»."}}},{"id":"L2-work","ctx":["L2-work"],"title":{"en":"Work talks: induction, training and careers","tr":"İş konuşmaları: oryantasyon, eğitim ve kariyer","fa":"صحبت‌های کاری: آشنایی، آموزش و شغل"},"asks":{"en":"A manager welcomes new staff, a trainer explains a job, or someone talks about a career. Questions ask about duties, rules, who is responsible for what, what the job needs and advice for new starters.","tr":"Bir yönetici yeni personeli karşılar, bir eğitmen işi anlatır ya da biri bir kariyerden söz eder. Sorular görevleri, kuralları, kimin neden sorumlu olduğunu, işin ne gerektirdiğini ve yeni başlayanlara tavsiyeleri sorar.","fa":"یک مدیر به کارکنان تازه خوش‌آمد می‌گوید، یک مربی کاری را توضیح می‌دهد، یا کسی درباره‌ی یک شغل حرف می‌زند. سؤال‌ها درباره‌ی وظایف، قانون‌ها، اینکه چه کسی مسئول چیست، شرایط کار و توصیه به تازه‌کارهاست."},"fields":["What should new staff do on the first day?","Who should staff report problems to?","What is the most important quality for this job?","Which TWO things must staff bring?","What is each person responsible for?","What advice does the speaker give?"],"words":[{"a":"induction","b":"your first day / the welcome session","tr":"oryantasyon","fa":"دوره‌ی آشنایی"},{"a":"rota","b":"the timetable of who works when","tr":"vardiya çizelgesi","fa":"جدول شیفت‌ها"},{"a":"report to","b":"the person you go to","tr":"... -e bağlı olmak","fa":"زیر نظر ... بودن"},{"a":"responsible for","b":"in charge of / looks after","tr":"... -den sorumlu","fa":"مسئولِ"},{"a":"health and safety","b":"the rules that stop accidents","tr":"iş sağlığı ve güvenliği","fa":"ایمنی و بهداشت کار"},{"a":"essential","b":"the one thing you must have","tr":"şart","fa":"ضروری"},{"a":"mentor","b":"an experienced colleague who helps you","tr":"deneyimli rehber, mentor","fa":"همکار باتجربه‌ی راهنما"},{"a":"sign in","b":"write your name when you arrive","tr":"giriş kaydı yapmak","fa":"ثبت ورود"},{"a":"overtime","b":"extra hours","tr":"fazla mesai","fa":"اضافه‌کاری"},{"a":"feedback","b":"we tell you how you're doing","tr":"geri bildirim","fa":"بازخورد"},{"a":"promotion","b":"a better job later on","tr":"terfi","fa":"ترفیع"},{"a":"qualification","b":"a certificate / training in","tr":"nitelik, diploma","fa":"مدرک"}],"traps":[{"en":"Names and roles: several people are introduced. Match each one by what they do, not by the order you hear them.","tr":"İsimler ve görevler: birkaç kişi tanıtılır. Her birini duyduğun sıraya göre değil, yaptığı işe göre eşleştir.","fa":"اسم‌ها و نقش‌ها: چند نفر معرفی می‌شوند. هر کدام را با کاری که می‌کند جور کن، نه با ترتیبی که می‌شنوی."},{"en":"\"Most important\" against \"also useful\": several qualities are mentioned, but one is stressed.","tr":"\"En önemli\" ile \"bu da işe yarar\": birkaç nitelik söylenir ama biri vurgulanır.","fa":"«مهم‌ترین» در برابر «این هم مفید است»: چند ویژگی گفته می‌شود، ولی روی یکی تأکید می‌شود."},{"en":"Rules that changed: \"you used to..., but from now on...\". The answer is the new rule.","tr":"Değişen kurallar: \"eskiden..., ama artık...\". Cevap yeni kuraldır.","fa":"قانون‌هایی که عوض شده‌اند: «قبلاً...، ولی از این به بعد...». جواب قانون جدید است."}],"example":{"lines":[["Manager","Lots of people think you need a chef’s training for this job."],["Manager","You don’t. Speed comes with time, too."],["Manager","What really matters is staying calm when the kitchen gets busy."]],"item":"What does the manager say is most important?  A cooking qualifications   B staying calm under pressure   C working fast","answer":"B","why":{"en":"Training is rejected and speed \"comes with time\". \"What really matters\" stresses staying calm.","tr":"Eğitim gereksiz deniyor, hız da \"zamanla gelir\". \"What really matters\" sakin kalmayı vurguluyor.","fa":"آموزش آشپزی لازم نیست و سرعت «با زمان می‌آید». «What really matters» روی آرام ماندن تأکید می‌کند."}},"general":true,"patterns":["L2-work"],"often":{"pattern":"L2-work","n":9,"of":40,"label":{"en":"Comes up often in the real exam: 9 of the last 40 tests","tr":"Gerçek sınavda sık çıkar: son 40 sınavın 9’unda","fa":"در آزمون واقعی زیاد می‌آید: در ۹ آزمون از ۴۰ آزمونِ اخیر"}}}]},"points":[{"eyebrow":{"en":"In the exam","tr":"Sınavda","fa":"در آزمون"},"head":{"en":"Three formats in ten questions","tr":"On soruda üç format","fa":"سه شکل سؤال در ده سؤال"},"body":{"en":"Questions 11-14 are two choose-TWO questions (A-E). Questions 15-16 are ordinary multiple choice (A-C). After a short break, Questions 17-20 match four topics to a box of six; two letters are not used.","tr":"Soru 11-14 iki tane iki-seçenekli sorudur (A-E). Soru 15-16 normal çoktan seçmelidir (A-C). Kısa bir aradan sonra Soru 17-20 dört konuyu altı seçenekli bir kutuyla eşleştirir; iki harf kullanılmaz.","fa":"سؤال‌های ۱۱ تا ۱۴ دو سؤالِ «دو گزینه» هستند (A تا E). سؤال‌های ۱۵ و ۱۶ چندگزینه‌ای معمولی‌اند (A تا C). بعد از یک مکث کوتاه، سؤال‌های ۱۷ تا ۲۰ چهار موضوع را به یک کادر شش‌تایی وصل می‌کنند؛ دو حرف استفاده نمی‌شوند."}},{"eyebrow":{"en":"The method","tr":"Yöntem","fa":"روش"},"head":{"en":"Listen for the decision","tr":"Kararı dinle","fa":"به تصمیم گوش بده"},"steps":[{"en":"In the reading time, underline the key idea of each option.","tr":"Okuma süresinde her seçeneğin anahtar fikrinin altını çiz.","fa":"در زمان خواندن زیر ایده‌ی کلیدی هر گزینه خط بکش."},{"en":"Expect every option to be mentioned. Tick it only when the speaker confirms it; cross it out when she rejects it.","tr":"Her seçenekten söz edileceğini bekle. Konuşan doğruladığında işaretle; reddettiğinde üstünü çiz.","fa":"انتظار داشته باش از همه‌ی گزینه‌ها حرف زده شود. فقط وقتی تیک بزن که گوینده تأییدش کند؛ وقتی ردش کرد، خطش بزن."},{"en":"In the matching task, the topics come in order: write the letter as soon as the advice is clear, then move to the next topic.","tr":"Eşleştirmede konular sırayla gelir: tavsiye netleşir netleşmez harfi yaz, sonra sonraki konuya geç.","fa":"در جورکردن موضوع‌ها به ترتیب می‌آیند: همین که توصیه روشن شد حرف را بنویس و برو سراغ موضوع بعدی."}]},{"eyebrow":{"en":"The trap","tr":"Tuzak","fa":"دام"},"head":{"en":"What people think vs what she did","tr":"İnsanların düşündüğü ile onun yaptığı","fa":"فکرِ مردم در برابر کارِ او"},"body":{"en":"Speakers in Part 2 often say what others believe (\"everyone assumes\", \"people often ask\") or what they nearly did (\"I did think about...\"). These are distractors. The answer is what the speaker actually did or recommends.","tr":"Part 2’deki konuşanlar çoğu zaman başkalarının neye inandığını (\"everyone assumes\", \"people often ask\") ya da neredeyse yaptıklarını (\"I did think about...\") söyler. Bunlar çeldiricidir. Cevap, konuşanın gerçekten yaptığı ya da önerdiği şeydir.","fa":"گوینده‌های Part 2 اغلب می‌گویند دیگران چه باور دارند («everyone assumes»، «people often ask») یا چه کاری را تقریباً کردند («I did think about...»). این‌ها گزینه‌ی انحرافی‌اند. جواب کاری است که گوینده واقعاً کرده یا توصیه می‌کند."}}],"example":{"eyebrow":{"en":"Worked example","tr":"Çözümlü örnek","fa":"مثال حل‌شده"},"head":{"en":"One choose-TWO question, step by step","tr":"Bir iki-seçenekli soru, adım adım","fa":"یک سؤال «دو گزینه»، قدم به قدم"},"instruction":"Which TWO things did the speaker do before opening her bakery? A took a baking course  B worked in a bakery  C borrowed from a bank  D tested recipes on friends  E bought a van","item":"Choose TWO letters.","lines":[["Speaker","I thought about a baking course, but I learned on the job instead, working nights in a bakery. I paid for everything myself, no bank loan. And every weekend my friends tried my new recipes."]],"answer":"B and D","walk":[{"en":"A is mentioned with \"I thought about... but\": not done.","tr":"A \"düşündüm... ama\" ile söyleniyor: yapılmamış.","fa":"A با «فکرش را کردم... اما» آمده: انجام نشده."},{"en":"C is ruled out: \"no bank loan\". E is never mentioned.","tr":"C eleniyor: \"banka kredisi yok\". E hiç söylenmiyor.","fa":"C رد می‌شود: «بدون وام بانکی». E اصلاً گفته نمی‌شود."},{"en":"\"Working nights in a bakery\" (B) and friends trying recipes (D): write B and D.","tr":"\"Bir fırında gece çalışmak\" (B) ve tarifleri deneyen arkadaşlar (D): B ve D yaz.","fa":"«شب‌ها در یک نانوایی کار کردن» (B) و دوست‌هایی که دستورها را امتحان می‌کردند (D): B و D را بنویس."}]},"quick":{"prompt":"You hear: \"People assume I wanted a stall because I love being outside. Honestly, it was about the hours: I can be home every afternoon.\" Why did she choose a stall?","options":["being outdoors","the money","the working hours"],"correct":2,"why":{"en":"\"People assume\" gives the distractor (being outside). \"Honestly, it was about the hours\" gives the reason.","tr":"\"People assume\" çeldiriciyi verir (dışarıda olmak). \"Açıkçası saatlerle ilgiliydi\" nedeni verir.","fa":"«people assume» گزینه‌ی انحرافی را می‌دهد (بیرون بودن). «راستش به‌خاطر ساعت‌ها بود» دلیل را می‌گوید."}},"remember":{"en":"Every option is mentioned: tick only what the speaker actually did or advises.","tr":"Her seçenekten söz edilir: yalnızca konuşanın gerçekten yaptığını ya da önerdiğini işaretle.","fa":"از همه‌ی گزینه‌ها حرف زده می‌شود: فقط چیزی را علامت بزن که گوینده واقعاً کرده یا توصیه می‌کند."},"type":"explain","id":"c-x03-l2-e","course":"ielts-exams","exam":"exam-03","unit":"x03-l2"},"drill":{"type":"drill","skill":"listening","part":"Listening Part 2","title":{"en":"Starting a market coffee stall","tr":"Pazarda kahve tezgâhı açmak","fa":"راه‌اندازی یک غرفه‌ی قهوه در بازار"},"timed":7,"ctx":["L2-work"],"script":[{"who":"Owner","line":"Hi, everyone. Thanks for inviting me. My name's Dana Kowalski, and for the last three years I've run a coffee stall called Steady Brew at the Saturday market in Millbank Square. Your teacher asked me to tell you how I got started and what I've learned, so here goes."},{"who":"Owner","line":"Before I opened the stall, I did two things that I'd recommend to anyone. First, I worked in a busy café for a whole year. I learned more about coffee, and about customers, in that year than I could ever have learned from a book. I did think about doing a business course at the college, but in the end I couldn't afford the time."},{"who":"Owner","line":"The second thing I did was visit other markets, lots of them, on Saturday mornings. I didn't buy much; I just watched. Where did people queue? What time was it busiest? Which stalls looked friendly and which didn't? That told me a lot about where to put my stall and what it should look like. For the money, I used my own savings. My family offered to lend me some, but I didn't want that pressure. And I didn't design the logo myself: a friend who's a graphic designer did it for a very fair price."},{"who":"Owner","line":"So, the first year. I won't pretend it was easy. The weather was the biggest problem. When it rains at an outdoor market, people simply don't come, and that first winter there were weeks when I sold almost nothing. The other problem was my coffee machine, which broke down twice in the first six months, and both times I lost a whole Saturday's takings. People often ask whether customers complained about the prices, but actually they didn't; most of them were happy to pay a bit more for good coffee. And I work alone, so I've never had any trouble with staff."},{"who":"Owner","line":"A question I'm always asked is why I chose a market rather than a little shop. Everyone assumes it's because the rent is lower. And yes, it is cheaper, but that wasn't really the reason. The real advantage is that I can try out a new idea one Saturday, and if it doesn't work, I just stop. In a shop, every mistake costs you for months. I also enjoy being outdoors, I suppose, but that's a bonus, not the reason."},{"who":"Owner","line":"One thing nobody warned me about was the licence. You need a licence from the council to trade at the market, and I assumed I'd get it in a week or two. In fact it took almost three months, because of all the hygiene checks. It wasn't expensive, and you only renew it once a year, but please apply early."},{"who":"Owner","line":"Now, I promised your teacher some practical advice, so let me go through a few areas quickly."},{"who":"Owner","line":"First, prices. Don't set them once and forget about them. The cost of milk and coffee beans goes up and down all the time, so I'd say look at your prices every single month. That's what keeps you in business."},{"who":"Owner","line":"Social media. It's important, but it can eat your whole week if you let it. I post one photo a day, usually before the market opens, and that's it. My advice is not to spend too much time on it."},{"who":"Owner","line":"Then suppliers. When I started, I spent weeks searching online for the best coffee and milk suppliers. What I should have done is ask the other stallholders who they use. They know who delivers on time and who doesn't, and most of them are very happy to tell you."},{"who":"Owner","line":"Some people swear by free samples to bring customers in. I tried it for a month and it didn't really work for me; people took the free cup and walked on. And an accountant is worth having eventually, but you don't need one on day one."},{"who":"Owner","line":"And finally, the menu. When I opened, I offered twelve different drinks, and the queue moved very slowly. Now I have five. Keep it simple: do a few things really well, and people will come back."},{"who":"Owner","line":"Right, I think that's everything. I'm happy to answer any questions, and if you come to Millbank Square on Saturday, the first coffee's on me."}],"groups":[{"instruction":"Questions 11-12. Choose TWO letters, A-E.","qtype":"mcq2","questions":[{"n":11,"n2":12,"kind":"mcq2","prompt":"Which TWO things did Dana do before she opened her stall?","options":["A She took a business course.","B She worked in a café.","C She borrowed money from her family.","D She designed her own logo.","E She studied how other markets worked."],"correct":[1,4],"evidence":"I worked in a busy café for a whole year","trap":["TR-ruledout","TR-paraphrase"],"why":{"en":"B \"I worked in a busy café for a whole year\" and E \"I visited other markets... I just watched\". She only thought about the course, refused her family’s loan, and a friend designed the logo.","tr":"B \"Bir yıl boyunca yoğun bir kafede çalıştım\" ve E \"Başka pazarları gezdim... sadece izledim\". Kursu yalnızca düşündü, ailesinin borç teklifini kabul etmedi, logoyu da bir arkadaşı tasarladı.","fa":"B «یک سال کامل در یک کافه‌ی شلوغ کار کردم» و E «بازارهای دیگر را گشتم... فقط نگاه کردم». به دوره فقط فکر کرد، قرض خانواده را قبول نکرد و لوگو را یک دوست طراحی کرد."}}]},{"instruction":"Questions 13-14. Choose TWO letters, A-E.","qtype":"mcq2","questions":[{"n":13,"n2":14,"kind":"mcq2","prompt":"Which TWO problems did Dana have in her first year?","options":["A Customers complained about her prices.","B Bad weather kept customers away.","C Her staff kept leaving.","D Her coffee machine stopped working.","E There was nowhere for customers to park."],"correct":[1,3],"evidence":"The weather was the biggest problem","trap":["TR-ruledout","TR-paraphrase"],"why":{"en":"B \"When it rains... people simply don’t come\" and D the machine \"broke down twice\". Customers did not complain about prices, she works alone, and parking is not mentioned.","tr":"B \"Yağmur yağınca... insanlar gelmiyor\" ve D makine \"iki kez bozuldu\". Müşteriler fiyatlardan şikâyet etmedi, tek başına çalışıyor ve otoparktan söz edilmiyor.","fa":"B «وقتی باران می‌آید... مردم نمی‌آیند» و D دستگاه «دو بار خراب شد». مشتری‌ها از قیمت شکایت نکردند، او تنها کار می‌کند و از پارکینگ حرفی نیست."}}]},{"instruction":"Questions 15-16. Choose the correct letter, A, B or C.","qtype":"mcq","questions":[{"n":15,"kind":"mcq","prompt":"Why did Dana choose a market rather than a shop?","options":["A The rent is lower.","B She can try out new ideas easily.","C She prefers working outdoors."],"correct":1,"evidence":"The real advantage is that I can try out a new idea","why":{"en":"The lower rent is what \"everyone assumes\", and being outdoors is \"a bonus\". \"The real advantage is that I can try out a new idea.\"","tr":"Düşük kira \"herkesin sandığı\" şey, dışarıda olmak ise \"bir artı\". \"Asıl avantaj yeni bir fikri deneyebilmem.\"","fa":"اجاره‌ی کمتر چیزی است که «همه فکر می‌کنند» و بیرون بودن «یک امتیاز اضافه» است. «مزیت اصلی این است که می‌توانم ایده‌ی تازه‌ای را امتحان کنم»."},"trap":["TR-ruledout"]},{"n":16,"kind":"mcq","prompt":"What does Dana say about her market licence?","options":["A It took longer to get than she expected.","B It was very expensive.","C It has to be renewed every month."],"correct":0,"evidence":"In fact it took almost three months","why":{"en":"She expected a week or two; \"in fact it took almost three months\". It was not expensive and is renewed once a year.","tr":"Bir iki hafta bekliyordu; \"aslında neredeyse üç ay sürdü\". Pahalı değildi ve yılda bir yenileniyor.","fa":"انتظار یکی دو هفته را داشت؛ «در واقع تقریباً سه ماه طول کشید». گران نبود و سالی یک بار تمدید می‌شود."},"trap":["TR-ruledout","TR-paraphrase"]}]},{"instruction":"Questions 17-20. What advice does Dana give about each of the following? Choose FOUR answers from the box and write the correct letter, A-F, next to Questions 17-20.","qtype":"matching","bank":["A Keep it simple.","B Check it every month.","C Ask other stallholders.","D Limit the hours you give it.","E Get help from an accountant.","F Give some away free."],"questions":[{"n":17,"kind":"match","prompt":"prices","correct":1,"evidence":"look at your prices every single month","why":{"en":"\"Look at your prices every single month\" = check them every month.","tr":"\"Fiyatlarına her ay bak\" = her ay kontrol et.","fa":"«هر ماه قیمت‌هایت را نگاه کن» یعنی هر ماه چکشان کن."},"trap":["TR-paraphrase"]},{"n":18,"kind":"match","prompt":"social media","correct":3,"evidence":"not to spend too much time on it","why":{"en":"\"It can eat your whole week... my advice is not to spend too much time on it.\"","tr":"\"Bütün haftanı yiyebilir... tavsiyem ona çok vakit ayırmaman.\"","fa":"«می‌تواند کل هفته‌ات را بخورد... توصیه‌ام این است که وقت زیادی رویش نگذاری»."},"trap":["TR-paraphrase"]},{"n":19,"kind":"match","prompt":"suppliers","correct":2,"evidence":"ask the other stallholders who they use","why":{"en":"Searching online took weeks; she should have asked \"the other stallholders who they use\".","tr":"İnternette aramak haftalar sürdü; \"diğer tezgâh sahiplerine kimi kullandıklarını\" sormalıydı.","fa":"جستجوی اینترنتی هفته‌ها طول کشید؛ باید از «غرفه‌دارهای دیگر می‌پرسید با چه کسی کار می‌کنند»."},"trap":["TR-paraphrase","TR-ruledout"]},{"n":20,"kind":"match","prompt":"the menu","correct":0,"evidence":"Keep it simple","why":{"en":"Free samples \"didn’t really work\" and an accountant is for later. For the menu: \"Keep it simple.\"","tr":"Ücretsiz numuneler \"pek işe yaramadı\", muhasebeci de daha sonrası için. Menü için: \"Basit tut.\"","fa":"نمونه‌ی رایگان «زیاد جواب نداد» و حسابدار برای بعدهاست. برای منو: «ساده نگهش دار»."},"trap":["TR-ruledout"]}]}],"audio":{"voices":{"Announcer":{"accent":"British (standard Southern)","gender":"M","tts":{"engine":"kokoro","voice":"bm_george"},"role":"Recorded rubric"},"Owner":{"accent":"North American","gender":"F","tts":{"engine":"kokoro","voice":"af_heart"},"role":"Coffee-stall owner (guest speaker)"}},"sequence":[{"type":"announcer","text":"Part 2. You will hear the owner of a market coffee stall talking to a business class about how she started. First, you have some time to look at Questions 11 to 16."},{"type":"pause","seconds":30,"note":"reading time, Questions 11-16"},{"type":"announcer","text":"Now listen carefully and answer Questions 11 to 16."},{"type":"sfx","note":"small classroom: quiet room tone, a little applause at the very start"},{"type":"lines","from":0,"to":5},{"type":"announcer","text":"Before you hear the rest of the talk, you have some time to look at Questions 17 to 20."},{"type":"pause","seconds":30,"note":"reading time, Questions 17-20"},{"type":"announcer","text":"Now listen and answer Questions 17 to 20."},{"type":"lines","from":6,"to":12},{"type":"announcer","text":"That is the end of Part 2. You now have half a minute to check your answers.","after":30}]},"id":"c-x03-l2-d","course":"ielts-exams","exam":"exam-03","unit":"x03-l2"},"exit":{"type":"exit","items":[{"tests":"word","point":1,"prompt":"The money that a stall or shop makes in one day is called its...","options":["savings","takings","licence"],"correct":1,"why":{"en":"Takings = the money taken from customers in a day.","tr":"Takings = bir günde müşterilerden alınan para.","fa":"takings یعنی پولی که در یک روز از مشتری‌ها گرفته می‌شود."}},{"tests":"paraphrase","point":1,"prompt":"Which phrase means \"stop working\", for a machine?","options":["break down","break even","break in"],"correct":0,"why":{"en":"A machine that breaks down stops working. To break even is to make no profit and no loss.","tr":"Bozulan (break down) makine çalışmayı bırakır. Break even, ne kâr ne zarar etmektir.","fa":"دستگاهی که break down می‌شود از کار می‌افتد. break even یعنی نه سود و نه ضرر."}},{"tests":"method","point":2,"prompt":"A matching task has four topics and a box of six letters. What does this tell you?","options":["one topic has two answers","two topics are left empty","two letters will not be used"],"correct":2,"why":{"en":"Choose FOUR answers from six: each topic gets one letter, and two are left over.","tr":"Altıdan DÖRT cevap seç: her konuya bir harf düşer, ikisi artar.","fa":"از شش تا چهار جواب انتخاب کن: هر موضوع یک حرف می‌گیرد و دو تا اضافه می‌مانند."}},{"tests":"trap","point":3,"prompt":"\"I did think about taking a loan, but in the end I used my savings.\" Did the speaker take a loan?","options":["Yes","No","The speaker doesn’t say"],"correct":1,"why":{"en":"\"I did think about... but in the end\" means she did not do it.","tr":"\"Düşündüm... ama sonunda\" bunu yapmadığı anlamına gelir.","fa":"«فکرش را کردم... اما آخرش» یعنی انجامش نداد."}},{"tests":"trap","point":2,"prompt":"\"Some people give free samples. I tried it, and it didn’t work for me.\" Is \"Give free samples\" her advice?","options":["No: she mentions it but does not recommend it","Yes: she mentions it","Only for new businesses"],"correct":0,"why":{"en":"Mentioned is not the same as advised: she tried it and rejected it.","tr":"Söz etmek tavsiye etmek değildir: denedi ve vazgeçti.","fa":"اسم بردن با توصیه کردن یکی نیست: امتحانش کرد و کنارش گذاشت."}}],"id":"c-x03-l2-x","course":"ielts-exams","exam":"exam-03","unit":"x03-l2"}}; })(globalThis.IELTS_EXAMS = globalThis.IELTS_EXAMS || {});
